,"type":"adjValue"},{"id":"839ead40-7e5a-4f4b-8d19-f5a48d150fb9","data":{"value":{"value":1},"variable":"ATTRIBUTE_CON"},"type":"adjValue"}],"falseOperations":[{"id":"d4dacac7-1456-4fb4-a23c-69b155ff0c4a","data":{"value":{"value":1},"variable":"ATTRIBUTE_CON"},"type":"adjValue"}]}}],"description":"Your companion races. It gains a +10-foot status bonus to its Speed, swim Speed, or fly Speed (your choice). Its proficiency in Fortitude saves increases to legendary, and its Constitution modifier increases by 1."},{"id":"75f7d039-7200-447e-a08e-65c1c22c6182","type":"CUSTOM","title":"Tracker","operations":[{"id":"a4716511-49b6-4f0a-895a-cfed4336f11c","data":{"conditions":[{"id":"79e036de-59e5-4cb2-9cf0-5c1f46ac5bc5","data":{"name":"SKILL_SURVIVAL","type":"prof","value":{"value":"U","attribute":"ATTRIBUTE_WIS","increases":0}},"name":"SKILL_SURVIVAL","type":"prof","value":"E","operator":"GREATER_THAN_OR_EQUALS"}],"trueOperations":[{"id":"864113eb-1bac-42fd-bf34-fcde38a72741","data":{"value":{"value":"M"},"variable":"SKILL_SURVIVAL"},"type":"adjValue"}],"falseOperations":[{"id":"5857facb-f7b9-4d66-b10b-2fb336be79ae","data":{"value":{"value":"E"},"variable":"SKILL_SURVIVAL"},"type":"adjValue"}]},"type":"conditional"},{"id":"104091cc-aa80-4030-b5f2-bb2309993d8a","type":"conditional","data":{"conditions":[{"id":"45d01d41-0c7c-4259-ab61-41b8d6bee244","name":"ATTRIBUTE_WIS","type":"attr","operator":"GREATER_THAN_OR_EQUALS","value":"4"}],"trueOperations":[{"id":"173a324c-50fc-44d4-8e6a-eb2d983dcc85","data":{"value":{"value":1},"variable":"ATTRIBUTE_WIS"},"type":"adjValue"},{"id":"418cd624-9410-435a-968b-846c69353ff3","data":{"value":{"value":1},"variable":"ATTRIBUTE_WIS"},"type":"adjValue"}],"falseOperations":[{"id":"0092c0c8-ec8d-44ec-9a15-a69a953701a4","data":{"value":{"value":1},"variable":"ATTRIBUTE_WIS"},"type":"adjValue"}]}}],"description":"Your companion is an incredible tracker. It can move at full Speed while following tracks. Its proficiency rank in Survival increases to expert (or master if it was already an expert from its type), and its Wisdom modifier increases by 1."},{"id":"a584d690-e56f-448a-891b-4e12af0f8fdb","type":"CUSTOM","title":"Wrecker","operations":[{"id":"582908c1-9881-4580-b668-4311d9b460d3","data":{"value":{"value":"M"},"variable":"SKILL_ATHLETICS"},"type":"adjValue"},{"id":"02f1b928-f194-4b0a-9ddc-1c1d48a34622","type":"conditional","data":{"conditions":[{"id":"0cf1d243-2d8b-4755-8847-2de6d9e2764f","name":"ATTRIBUTE_STR","type":"attr","operator":"GREATER_THAN_OR_EQUALS","value":"4"}],"trueOperations":[{"id":"644a1701-543a-4864-8119-9c4b75bbec7e","data":{"value":{"value":1},"variable":"ATTRIBUTE_STR"},"type":"adjValue"},{"id":"88322416-4ac9-441b-86b6-b8e96874939a","data":{"value":{"value":1},"variable":"ATTRIBUTE_STR"},"type":"adjValue"}],"falseOperations":[{"id":"34cb832a-4f7d-40c5-894d-f9000d569654","data":{"value":{"value":1},"variable":"ATTRIBUTE_STR"},"type":"adjValue"}]}}],"description":"Your companion smashes things. Its unarmed attacks ignore half an object's Hardness. Its Athletics proficiency increases to master, and its Strength modifier increases by 1."}]},"type":"select"}],"adjusted":9}],"sources":[{"id":1,"name":"Player Core","user_id":null,"is_published":true,"require_key":false,"required_content_sources":[],"group":"pathfinder-core","deprecated":null}],"primary":["https://2e.aonprd.com/Rules.aspx?ID=2117","https://2e.aonprd.com/Rules.aspx?ID=2118","https://2e.aonprd.com/Rules.aspx?ID=2119","https://2e.aonprd.com/Rules.aspx?ID=2120"]}$advancements$::jsonb as spec),
blocks as(select value as patch from settings cross join lateral jsonb_array_elements(spec->'blocks'))
select 'animal-companion-full-increases'::text as id,coalesce((
  (select count(*)=5 and bool_and((a.id is not null
    and ((to_jsonb(a)||jsonb_build_object('uuid',a.uuid::text))-'{created_at,updated_at,search_tsv,operations}'::text[]) is not distinct from patch->'anchor'
    and to_jsonb(a.operations) is not distinct from patch->'after') is true) from blocks left join public.ability_block a on a.id=(patch->>'id')::bigint)
  and (select count(*)=1 and bool_and((s.id is not null and jsonb_typeof(s.meta_data::jsonb)='object'
    and not exists(select 1 from jsonb_each(source_spec) e where to_jsonb(s)->e.key is distinct from e.value)) is true)
    from settings cross join lateral jsonb_array_elements(spec->'sources') source_specs(source_spec) left join public.content_source s on s.id=(source_spec->>'id')::bigint)
  and not exists(select 1 from public.content_update u where coalesce(u.status->>'state','PENDING') not in ('APPROVED','REJECTED') and (
    (u.type='content-source' and exists(select 1 from jsonb_array_elements(spec->'sources') s where u.ref_id=(s->>'id')::bigint or u.data->>'id'=s->>'id' or lower(btrim(u.data->>'name'))=lower(btrim(s->>'name'))))
    or (u.type='ability-block' and exists(select 1 from jsonb_array_elements(spec->'blocks') p where u.ref_id=(p->>'id')::bigint or u.data->>'id'=p->>'id' or u.data->>'uuid'=p#>>'{anchor,uuid}' or ((u.content_source_id=(p#>>'{anchor,content_source_id}')::bigint or u.data->>'content_source_id'=p#>>'{anchor,content_source_id}') and lower(btrim(u.data->>'name'))=lower(btrim(p#>>'{anchor,name}')))))
  ))
),false) as passed from settings
)
select original_checks.id,case when coalesce((status.value->>'recognized')::boolean,true) then coalesce((status.value->>'passed')::boolean,false) else original_checks.passed end as passed from original_checks cross join terminal_status status;
